import{_ as e,a as t,c as r,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"易经：一卦的阅读步骤与解释边界","description":"用既济、泰否和乾卦演示卦辞、爻辞、彖象、时位关系的阅读方法，避免把结构条件变成万能判卦公式。","frontmatter":{"title":"易经：一卦的阅读步骤与解释边界","description":"用既济、泰否和乾卦演示卦辞、爻辞、彖象、时位关系的阅读方法，避免把结构条件变成万能判卦公式。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"易经专题","summary":"用既济、泰否和乾卦演示卦辞、爻辞、彖象、时位关系的阅读方法，避免把结构条件变成万能判卦公式。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"易经：八卦名称、性质与取象","link":"/life/personal/yijing/trigrams"},"next":{"text":"易经：六十四卦索引与上下卦查表","link":"/life/personal/yijing/hexagram-index"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"易经：八卦名称、性质与取象","link":"/life/personal/yijing/trigrams"},"next":{"text":"易经：六十四卦索引与上下卦查表","link":"/life/personal/yijing/hexagram-index"}},"headers":[],"relativePath":"life/personal/yijing/hexagram-reading.md","filePath":"life/personal/yijing/hexagram-reading.md"}'),i={name:"life/personal/yijing/hexagram-reading.md"};function s(l,a,d,o,p,h){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="易经-一卦的阅读步骤与解释边界" tabindex="-1">易经：一卦的阅读步骤与解释边界 <a class="header-anchor" href="#易经-一卦的阅读步骤与解释边界" aria-label="Permalink to &quot;易经：一卦的阅读步骤与解释边界&quot;">​</a></h1><p>读一卦最常见的困难，是把原文、解释和自己的联想同时读成一句话。比较可靠的方法是先拆开文本，再重新建立关联。本篇的步骤是学习用的整理方式，不是某一派唯一的断卦法。</p><h2 id="先分清页面上的五种材料" tabindex="-1">先分清页面上的五种材料 <a class="header-anchor" href="#先分清页面上的五种材料" aria-label="Permalink to &quot;先分清页面上的五种材料&quot;">​</a></h2><table tabindex="0"><thead><tr><th>材料</th><th>作用</th><th>以乾为例</th></tr></thead><tbody><tr><td>卦名与卦画</td><td>标明六画组合与名称</td><td>乾，上下皆乾</td></tr><tr><td>卦辞</td><td>整卦的经文判断</td><td>“元亨，利贞”</td></tr><tr><td>爻辞</td><td>各爻处境、形象和判断</td><td>初九“潜龙勿用”；上九“亢龙有悔”</td></tr><tr><td>彖传</td><td>解释整卦意义及其构成</td><td>“大哉乾元”等</td></tr><tr><td>象传</td><td>大象释全卦，小象释具体爻</td><td>大象“天行健”；初九小象“阳在下也”</td></tr></tbody></table><p>乾坤还附有《文言》。传世的经传合编本把这些文字排在一起，阅读便利，却不表示它们在同一时间由同一作者写成。表中引文与完整文本可在<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%B9%BE" target="_blank" rel="noopener noreferrer">《周易·乾》</a>核对，书籍层次另见<a href="./text-history">成书与版本</a>。</p><h2 id="第一步-确定是哪一个卦" tabindex="-1">第一步：确定是哪一个卦 <a class="header-anchor" href="#第一步-确定是哪一个卦" aria-label="Permalink to &quot;第一步：确定是哪一个卦&quot;">​</a></h2><p>先记卦名、通行序号、下卦和上卦，再核对六爻。不要只看六画卦的 Unicode 字符：不同设备的字体可能显示不完整；本专题的<a href="./hexagram-index">本地图谱</a>和上下卦文字可用于互相校验。</p><p>例如既济是第 63 卦，下离上坎；从下向上是阳、阴、阳、阴、阳、阴。若把上下卦反放，就成了未济。确认结构是阅读的前提，结构本身却还没有告诉我们全部卦义。</p><h2 id="第二步-把卦辞拆成条件与判断" tabindex="-1">第二步：把卦辞拆成条件与判断 <a class="header-anchor" href="#第二步-把卦辞拆成条件与判断" aria-label="Permalink to &quot;第二步：把卦辞拆成条件与判断&quot;">​</a></h2><p><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A2%E6%BF%9F" target="_blank" rel="noopener noreferrer">既济卦辞</a>有“利贞”“初吉终乱”。不要只截取“吉”，更不能因为卦名像“已经成功”就把整卦解释为万事大吉。对于“亨小／小亨”等断句和解释，需要联系具体版本与注家，逐卦页会给出采用的读法。</p><p>一段卦辞可以按以下问题做笔记：</p><ul><li>谁、什么事或什么处境是讨论对象？</li><li>原文是在说可行、有利、危险、悔恨，还是无过咎？</li><li>有没有“利”“不利”“勿”“有攸往”之类行动条件？</li><li>同一句中有没有阶段转折或对立判断？</li></ul><p>“利涉大川”也不必在任何场合都照字面解释成过河；但如果解释为承担困难事业，仍应标明这是一种传统引申，而不是原文原本就在说现代职业选择。</p><h2 id="第三步-逐爻读-先不求一个统一口号" tabindex="-1">第三步：逐爻读，先不求一个统一口号 <a class="header-anchor" href="#第三步-逐爻读-先不求一个统一口号" aria-label="Permalink to &quot;第三步：逐爻读，先不求一个统一口号&quot;">​</a></h2><p>以乾为例，初爻潜藏，二爻显现，三爻勤勉警惕，四爻试跃，五爻飞龙，上爻亢极有悔。可以从中观察处境的递进，却不能推成“所有人都必须从基层升到最高层”。六爻既有发展关系，也各有独立的条件和形象。</p><p>读每一爻时至少记下“爻题—原句—关键词—判断—解释理由”。遇到古代祭祀、婚嫁、征伐和刑罚语汇，先查词义，不要马上换成“升职”“脱单”“赚钱”。这些词反映了文本所处的历史文化环境。</p><h2 id="第四步-看传文提供了哪一种理由" tabindex="-1">第四步：看传文提供了哪一种理由 <a class="header-anchor" href="#第四步-看传文提供了哪一种理由" aria-label="Permalink to &quot;第四步：看传文提供了哪一种理由&quot;">​</a></h2><p>既济《彖》说“刚柔正而位当”，用爻位说明其秩序；《大象》则说“水在火上”，进而提出“思患而豫防之”。二者都在解释同一卦，关注点却不同：一个谈结构与卦辞，一个由卦象引出行动上的省察。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A2%E6%BF%9F" target="_blank" rel="noopener noreferrer">原文出处</a>。</p><p>由此可见，“看出了一个象”与“已经给出了现代决策”之间还有一段论证。现代读者可以用“完成之后还应检查薄弱点”作为反思问题，但具体检查什么仍然要由现实证据决定。</p><h2 id="第五步-使用时、位、中、正、应" tabindex="-1">第五步：使用时、位、中、正、应 <a class="header-anchor" href="#第五步-使用时、位、中、正、应" aria-label="Permalink to &quot;第五步：使用时、位、中、正、应&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>可以问什么</th><th>必须避免的简化</th></tr></thead><tbody><tr><td>时</td><td>全卦面对的是等待、争讼、损益、困境还是变革？</td><td>把它固定为某天某时辰</td></tr><tr><td>位</td><td>此爻位于开始、内卦之中、内外交界或终极哪里？</td><td>把六位永久对应六个职业等级</td></tr><tr><td>中</td><td>是否处二、五？是否体现该卦语境中的适度？</td><td>“中”就是两边各退一半</td></tr><tr><td>正</td><td>阴阳与常见爻位是否相当？</td><td>当位一定吉，失位一定凶</td></tr><tr><td>应</td><td>一四、二五、三上之间如何联系？</td><td>阴阳相应便自动代表好婚姻</td></tr><tr><td>承、乘、比</td><td>相邻者如何支持、压迫或接近？</td><td>只凭上下关系判断现实中的某个人</td></tr></tbody></table><p>既济常被用作“全爻当位”的例子，却仍有“终乱”的警告。未济虽六爻皆不当位，其《彖》仍谈“刚柔应也”。结构提供解释条件，不替代原文的整体判断。参看<a href="./hexagrams-57-64#gua-63">既济与未济逐卦正文</a>。</p><h2 id="第六步-做对读-检验自己的解释" tabindex="-1">第六步：做对读，检验自己的解释 <a class="header-anchor" href="#第六步-做对读-检验自己的解释" aria-label="Permalink to &quot;第六步：做对读，检验自己的解释&quot;">​</a></h2><h3 id="泰与否-不是-天在上才合理" tabindex="-1">泰与否：不是“天在上才合理” <a class="header-anchor" href="#泰与否-不是-天在上才合理" aria-label="Permalink to &quot;泰与否：不是“天在上才合理”&quot;">​</a></h3><p>泰是地上天下，否是天上地下。如果只凭日常天空在上、大地在下的直觉，会以为否比泰正常。经传的解释却着重“交”与“不交”：泰《彖》谈天地交、上下交；否《彖》谈天地不交、上下不交。因此，这里的取象关心关系能否沟通，不能简单按自然物的空间摆放判断好坏。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B3%B0" target="_blank" rel="noopener noreferrer">泰原文</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%A6" target="_blank" rel="noopener noreferrer">否原文</a>。</p><h3 id="同一卦也有转折" tabindex="-1">同一卦也有转折 <a class="header-anchor" href="#同一卦也有转折" aria-label="Permalink to &quot;同一卦也有转折&quot;">​</a></h3><p>泰的上六有“城复于隍”；否的上九有“倾否，先否后喜”。因此，一看到“泰”就说结果一定好，看到“否”就说结果一定坏，会与同卦爻辞冲突。这也说明卦名不是一份固定吉凶评分表。</p><h3 id="注家的解释也要比较" tabindex="-1">注家的解释也要比较 <a class="header-anchor" href="#注家的解释也要比较" aria-label="Permalink to &quot;注家的解释也要比较&quot;">​</a></h3><p>王弼<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E7%95%A5%E4%BE%8B/%E6%98%8E%E5%BD%96" target="_blank" rel="noopener noreferrer">《周易略例·明彖》</a>强调统论一卦、理解主旨；<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E7%95%A5%E4%BE%8B/%E6%98%8E%E8%B1%A1" target="_blank" rel="noopener noreferrer">《明象》</a>又批评拘泥于象。其他注家可能更重视筮占、卦变、伦理实践或字义。比较时，要保留每一家的起点和论证，不能把各家有利于自己结论的话随意拼接。</p><h2 id="一份可复用的读书卡" tabindex="-1">一份可复用的读书卡 <a class="header-anchor" href="#一份可复用的读书卡" aria-label="Permalink to &quot;一份可复用的读书卡&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>卦名及序号：</span></span>
<span class="line"><span>下卦 / 上卦 / 六爻次序：</span></span>
<span class="line"><span>本次阅读的经文（保留原字和断句）：</span></span>
<span class="line"><span>重要词义及未解决的异文：</span></span>
<span class="line"><span>彖传怎样解释：</span></span>
<span class="line"><span>大象与小象怎样解释：</span></span>
<span class="line"><span>所参考注家及具体篇章：</span></span>
<span class="line"><span>自己的概括（与引文分开）：</span></span>
<span class="line"><span>一个不能由这段文字推出的结论：</span></span>
<span class="line"><span>下一次需要核对的问题：</span></span></code></pre></div><p>最后一项“不能推出什么”很有价值。例如乾九三谈勤勉警惕，不能据此推出“睡眠越少越好”；谦谈不自满，也不能推出“遭遇不公永远不能表达意见”。解释必须能接受原文和现实两方面的检验。</p><h2 id="自测与参考答案" tabindex="-1">自测与参考答案 <a class="header-anchor" href="#自测与参考答案" aria-label="Permalink to &quot;自测与参考答案&quot;">​</a></h2><p><strong>题目：</strong> 有人说：“既济六爻当位，所以此后不会出问题。”这句话错在哪里？</p><p><strong>参考答案：</strong> 第一，卦辞已经出现“初吉终乱”；第二，大象要求思患预防，恰好说明完成后的风险仍须处理；第三，爻位属于文本解释层，不能成为现实未来不会出问题的证据。</p><p><strong>题目：</strong> “天行健，君子以自强不息”是乾卦的卦辞吗？</p><p><strong>参考答案：</strong> 不是，是乾卦《大象》中的传文。乾卦卦辞是“元亨，利贞”。把层次说对，后面的解释才有依据。</p><p><a href="./overview">返回专题</a> · <a href="./hexagram-index">查六十四卦</a> · <a href="./reading-practice">阅读练习</a></p>`,38)])])}const u=e(i,[["render",s]]);export{g as __pageData,u as default};
